processor-info.script:

			String cmd = input.getText("cmd");

			if(cmd.equals("GET_ESTIMATE_LIST"))
            {
				String srch_text = input.getText("title");

	            StringBuffer addWhere = new StringBuffer();
		        if ( srch_text!=null && !srch_text.equals("") )
	            {
	                addWhere.append("and title like N'%" + srch_text + "%' ");
	            }
	            input.put("addWhere", addWhere.toString() );
	        }

	        if( "SET_NEW_RESULT".equals(cmd)){

	        	DataSet in = new DataSet();            	
            	in.put( "status", "3");
            	in.put( "estimate_cnt", 1);
            	in.put( "estimate_point", 100);
            	in.put( "estimate_pass_yn", "Y");
            	in.put( "user_class_seq_no" , input.getText("user_class_seq_no") );
            	executeSQL("SET_STATUS_END", connection, in, output);

            	in.put( "user_lecture_seq_no", input.getText("user_lecture_seq_no")) ;
            	executeSQL("GET_END_CNT", connection, in, output);
            	int _cnt = output.getInt("tot_cnt");

            	if( _cnt == 0 )
            	{
	            	in.put( "status", "03");
	            }else{	            	
            		in.put( "status", "01");
	            }	            
            	executeSQL("SET_LECTURE_STATUS", connection, in, output);
	            output.put("status", in.getText("status"));

            }else if( "GET_ANSWER_CHECK".equals(cmd)){

	        	executeSQL("DELETE_ESTIMATE_RESULT_ONE", connection, input, output);

            	executeSQL("SET_ESTIMATE_RESULT", connection, input, output);

            	executeSQL("GET_ANSWER_CHECK", connection, input, output);
            }else if( "SET_ESTIMATE_RESULT".equals(cmd)){

	        	executeSQL("DELETE_ESTIMATE_RESULT", connection, input, output);

				DataSet in = new DataSet();            	

				for(int idx=0; idx< input.getCount("estimate_seq_no"); idx++)
				{
					String estimate_seq_no = input.getText("estimate_seq_no" ,idx);
					String answer_str = input.getText("answr_ctnt_"+estimate_seq_no);
					if( answer_str == null || "".equals(answer_str) )answer_str = "0";
					in.put( "estimate_seq_no" , estimate_seq_no ,idx);
					in.put( "answer", answer_str , idx);
					in.put( "user_class_seq_no" , input.getText("user_class_seq_no") ,idx);
				}
            	executeSQL(cmd, connection, in, output);

            	in = new DataSet();
            	in.put( "user_lecture_seq_no", input.getText("user_lecture_seq_no")) ;
            	in.put( "user_class_seq_no", input.getText("user_class_seq_no")) ;
            	executeSQL("GET_POINT", connection, in, output);
            	int _point = output.getInt("point"); 

            	executeSQL("GET_CNT", connection, in, output);
            	int _estimate_cnt = output.getInt("estimate_cnt");
            	System.out.println( _estimate_cnt );
            	executeSQL("GET_CHECK_POINT", connection, in, output);
            	int _ch_point = output.getInt("estimate_pass_point"); 
            	String estimate_pass_yn = "N";
            	if( _ch_point <= _point) estimate_pass_yn = "Y";

            	if( "Y".equals(estimate_pass_yn ))
            	{
            		in.put( "status", "3");
            		in.put( "estimate_cnt", _estimate_cnt +1);
            	}else{
            		if( _estimate_cnt >= 4 )
	           		{
	            		in.put( "status", "4");
	            		in.put( "estimate_cnt", _estimate_cnt +1);          		
	            	}else{
	            		in.put( "status", "1");
	            		in.put( "estimate_cnt", _estimate_cnt +1);
	            	}
            	}
            	in.put( "estimate_point", _point);
            	in.put( "estimate_pass_yn", estimate_pass_yn);
            	executeSQL("SET_STATUS_END", connection, in, output);

                in.put( "user_lecture_seq_no", input.getText("user_lecture_seq_no")) ;
            	executeSQL("GET_END_CNT", connection, in, output);
            	int _cnt = output.getInt("tot_cnt");

            	if( _cnt == 0 )
            	{
	            	in.put( "user_lecture_seq_no", input.getText("user_lecture_seq_no")) ;
	            	in.put( "status", "03");
	            	executeSQL("SET_LECTURE_STATUS", connection, in, output);
	            }else{

            		if( _estimate_cnt >= 4 )
            		{
	            		if( "Y".equals(estimate_pass_yn ))
	            			in.put( "status", "01");
	            		else
	            			in.put( "status", "09");
	            	}else{
	            		if( "Y".equals(estimate_pass_yn ))
	            			in.put( "status", "01");
	            		else
	            			in.put( "status", "01");
	            	}	
	            	executeSQL("SET_LECTURE_STATUS", connection, in, output);
	            }

            }else if("SET_EXAM_LIST".equals(cmd) || "SET_EXAM_SELECT_LIST".equals(cmd) ){

            	executeSQL(cmd, connection, input, output);

            	DataSet inn = new DataSet();
            	inn.put("user_class_seq_no" , input.getText("user_class_seq_no") );
            	executeSQL("GET_EXAM_LIST", connection, inn, output);

            }else if("SET_STATUS_START".equals(cmd)){

            	executeSQL(cmd, connection, input, output);

            	DataSet inn = new DataSet();
            	inn.put("user_lecture_seq_no" , input.getText("user_lecture_seq_no") );
            	inn.put("user_class_seq_no" , input.getText("user_class_seq_no") );
            	inn.put( "status", "02");
            	executeSQL("SET_LECTURE_STATUS", connection, inn, output);

            }else{

				executeSQL(cmd, connection, input, output);
			}
